        target_travel_mm = random.uniform(MINIMUM_SEGMENT_TRAVEL_MM, MAXIMUM_SEGMENT_TRAVEL_MM)
        segment_travel_mm = 0.0
        started_ms = state.measurements.time_ms
        publish_segment(segment_index + 1)
